let log = flow.get("motionLog") || [];
if (msg.payload === "MOTION DETECTED"){
let now = new Date();

let date =
String(now.getDate()).padStart(2, '0') + "/" +
String(now.getMonth() + 1).padStart(2, '0') + "/" +
now.getFullYear();

let time =
String(now.getHours()).padStart(2, '0') + ":" +
String(now.getMinutes()).padStart(2, '0') + ":" +
String(now.getSeconds()).padStart(2, '0');
    log.unshift({
        Time: date + " " + time,
        Event: msg.payload
    });

    log = log.slice(0, 1);
    flow.set("motionLog", log);
    msg.payload = log;

    return msg;
}

return null;

flow.set("motion", msg.payload);

let light = flow.get("light");
if(msg.payload === "MOTION DETECTED" && light === "DARK"){
    node.send({payload: 1});
    let timer = flow.get("autoTimer");
    if(timer){
        clearTimeout(timer);
    }
    timer = setTimeout(function(){
        node.send({payload: 0});
    }, 30000);
    flow.set("autoTimer", timer);
}
return null;

let current = Number(msg.payload);

//Ignore sensor noise
if (current < 0.20){
    current = 0
}
// Voltage and Power Factor
const voltage = 230;
const pf = 1.0;

let power = current * voltage * pf;

// Round to 1 decimal place
msg.payload = Number(power.toFixed(1));

return msg;

let current = Number(msg.payload);

if (current < 0.20)
msg.payload = "STOPED";
else if (current < 3)
msg.payload = "RUNNING";
else if (current < 7)
msg.payload = "HIGH LOAD";
else
msg.payload = "OVERLOAD";

return msg;

let current = Number(msg.payload);

//Ignore sensor noise
if (current < 0.20){
    current = 0
}
msg.payload = Number(current);

return msg;

let power = Number(msg.payload);

let delta = power / 3600000;

let today = flow.get("todayEnergy") || 0;
let monthly = flow.get("monthlyEnergy") || 0;

today += delta;
monthly += delta;

flow.set("todayEnergy", today);
flow.set("monthlyEnergy", monthly);

msg.payload = {
    today: today,
    monthly: monthly
};

return msg;

let today = new Date();
if(today.getDate() === 1){
    flow.set("monthlyEnergy", 0);
    msg.payload = "0.0000 kWh";
    return msg;
}
return null;

let gasStatus = Number(msg.payload);
let alarmMuted = flow.get("alarmMuted") || false;

if (gasStatus <= 1200){
    flow.set("alarmMuted", false);
    msg.payload = "SAFE";
}
else if (alarmMuted) {
    msg.payload = "MUTE";
}
else if (gasStatus <= 1800){
    msg.payload = "WARNING";
}
else{
    msg.payload = "DANGER";
}

return msg;

let log = flow.get("gasLog") || [];
if (msg.payload === "WARNING" || msg.payload === "DANGER"){
    let now = new Date();

let date =
String(now.getDate()).padStart(2, '0') + "/" +
String(now.getMonth() + 1).padStart(2, '0') + "/" +
now.getFullYear();

let time =
String(now.getHours()).padStart(2, '0') + ":" +
String(now.getMinutes()).padStart(2, '0') + ":" +
String(now.getSeconds()).padStart(2, '0');
    log.unshift({
        Time: date + " " + time,
        Event: msg.payload
    });

    log = log.slice(0, 1);
    flow.set("gasLog", log);
    msg.payload = log;

    return msg;
}

return null;

let log = flow.get("over-powerLog") || [];
if (msg.payload === "HIGH" || msg.payload === "VERY HIGH"){
    let now = new Date();

let date =
String(now.getDate()).padStart(2, '0') + "/" +
String(now.getMonth() + 1).padStart(2, '0') + "/" +
now.getFullYear();

let time =
String(now.getHours()).padStart(2, '0') + ":" +
String(now.getMinutes()).padStart(2, '0') + ":" +
String(now.getSeconds()).padStart(2, '0');
    log.unshift({
        Time: date + " " + time,
        Event: msg.payload
    });

    log = log.slice(0, 1);
    flow.set("over-powerLog", log);
    msg.payload = log;

    return msg;
}

return null;

let powerStatus = Number(msg.payload);

if (powerStatus <= 90.0){
    msg.payload = "NORMAL";
}
else if (powerStatus <= 150.0){
    msg.payload = "HIGH";
}
else{
    msg.payload = "VERY HIGH";
}

return msg;

if (msg.payload === "OFFLINE"){
    msg.payload = 0;
    return msg;
}
return null;

if (msg.payload === "OFFLINE"){
    msg.payload = "NOT CONNECTED";
    return msg;
}
return null;

if (msg.payload === "OFFLINE"){
    msg.payload = "OFF";
    return msg;
}
return null;
